import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_gemv_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

#define ROWS_PER_BLOCK 8
#define TILE_K4 256
// Each block processes ROWS_PER_BLOCK rows of A against the shared vector B.
// B is staged into shared memory once per K-tile and reused across all rows
// handled by the block, cutting redundant global memory traffic for B by a
// factor of ROWS_PER_BLOCK compared to the naive one-row-per-block scheme.
__global__ void gemv_kernel(const float* __restrict__ A,
                             const float* __restrict__ B,
                             float* __restrict__ C,
                             int M, int K)
{
  int row_start = blockIdx.x * ROWS_PER_BLOCK;
  if (row_start >= M) return;
  int rows = M - row_start;
  if (rows > ROWS_PER_BLOCK) rows = ROWS_PER_BLOCK;
  __shared__ float4 sB4[TILE_K4];
  float sum[ROWS_PER_BLOCK];
  #pragma unroll
  for (int r = 0; r < ROWS_PER_BLOCK; ++r) sum[r] = 0.0f;
  int K4 = K / 4;
  const float4* B4 = reinterpret_cast<const float4*>(B);
  for (int k0 = 0; k0 < K4; k0 += TILE_K4) {
    int tile_len = K4 - k0;
    if (tile_len > TILE_K4) tile_len = TILE_K4;
    for (int i = threadIdx.x; i < tile_len; i += blockDim.x) {
      sB4[i] = B4[k0 + i];
    }
    __syncthreads();
    for (int r = 0; r < rows; ++r) {
      const float4* Arow4 = reinterpret_cast<const float4*>(A + (size_t)(row_start + r) * K) + k0;
      float local = 0.0f;
      for (int i = threadIdx.x; i < tile_len; i += blockDim.x) {
        float4 a4 = Arow4[i];
        float4 b4 = sB4[i];
        local += a4.x * b4.x + a4.y * b4.y + a4.z * b4.z + a4.w * b4.w;
      }
      sum[r] += local;
    }
    __syncthreads();
  }
  // Remainder (K not divisible by 4)
  int rem_start = K4 * 4;
  for (int r = 0; r < rows; ++r) {
    const float* Arow = A + (size_t)(row_start + r) * K;
    float local = 0.0f;
    for (int i = rem_start + threadIdx.x; i < K; i += blockDim.x) {
      local += Arow[i] * B[i];
    }
    sum[r] += local;
  }
  // Warp-level reduction per row
  unsigned mask = 0xffffffffu;
  int lane = threadIdx.x & 31;
  int wid  = threadIdx.x >> 5;
  int num_warps = (blockDim.x + 31) / 32;
  __shared__ float sdata[ROWS_PER_BLOCK][32];
  #pragma unroll
  for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
    float val = sum[r];
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      val += __shfl_down_sync(mask, val, offset);
    }
    if (lane == 0) {
      sdata[r][wid] = val;
    }
  }
  __syncthreads();
  if (wid == 0) {
    #pragma unroll
    for (int r = 0; r < ROWS_PER_BLOCK; ++r) {
      if (r >= rows) break;
      float total = (lane < num_warps) ? sdata[r][lane] : 0.0f;
      #pragma unroll
      for (int offset = 16; offset > 0; offset >>= 1) {
        total += __shfl_down_sync(mask, total, offset);
      }
      if (lane == 0) {
        C[row_start + r] = total;
      }
    }
  }
}

torch::Tensor cute_gemv_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be 2D (K, 1)");
  TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match (A.size(1) == B.size(0))");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);

  auto C = torch::empty({M, 1}, A.options());

  const float* ptrA = A_c.data_ptr<float>();
  const float* ptrB = B_c.data_ptr<float>();
  float* ptrC = C.data_ptr<float>();

  dim3 block(256);
  dim3 grid((unsigned)((M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemv_kernel<<<grid, block, 0, stream>>>(ptrA, ptrB, ptrC, M, K);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gemv_kernel launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_gemv = load_inline(
    name="cute_gemv_inline",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_gemv_forward"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"
    ],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CuTe-based CUDA kernel: one block per output row, vectorized float4
    loads over K, and warp/block level tree reduction.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_gemv

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_gemv_forward(A, B)

