// vectorized (float4) loads plus warp/block reduction.
__global__ void gemv_kernel(const float* __restrict__ A,
                             const float* __restrict__ B,
                             float* __restrict__ C,
                             int M, int K)
{
  int m = blockIdx.x;
  if (m >= M) return;

  // Full tensors via CuTe
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(K), make_stride(Int<1>{}));

  // Row m of A: shape (K), stride 1 (contiguous)
  Tensor gA = mA(m, _);

  float sum = 0.0f;

  // Vectorized part: recast contiguous chunks to float4
  int K4 = K / 4;
  if (K4 > 0) {
    Tensor gA_head = gA(make_coord(_)).compose(make_layout(make_shape(K4 * 4)));
    Tensor gA4 = recast<float4>(gA_head);
    Tensor gB_head = mB.compose(make_layout(make_shape(K4 * 4)));
    Tensor gB4 = recast<float4>(gB_head);

    for (int i = threadIdx.x; i < K4; i += blockDim.x) {
      float4 a4 = gA4(i);
      float4 b4 = gB4(i);
      sum += a4.x * b4.x + a4.y * b4.y + a4.z * b4.z + a4.w * b4.w;
